**`CheckoutPage.tsx`**
```tsx
import React, { useMemo, useState } from "react";
import "./CheckoutPage.css";
import type { CartItem, DeliveryAddress, AddressErrors } from "./types";

interface CheckoutPageProps {
  cartItems: CartItem[];
  onBackToCart: () => void;
  onPay: (address: DeliveryAddress) => Promise<void>;
  shippingFee?: number;
}

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: "",
  street: "",
  city: "",
  state: "",
  postalCode: "",
  country: "",
  phone: "",
};

function formatCurrency(amount: number): string {
  return amount.toLocaleString(undefined, {
    style: "currency",
    currency: "USD",
  });
}

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};

  if (!address.fullName.trim()) errors.fullName = "Full name is required.";
  if (!address.street.trim()) errors.street = "Street address is required.";
  if (!address.city.trim()) errors.city = "City is required.";
  if (!address.state.trim()) errors.state = "State/Province is required.";
  if (!address.postalCode.trim()) {
    errors.postalCode = "Postal code is required.";
  } else if (!/^[A-Za-z0-9\s-]{3,10}$/.test(address.postalCode.trim())) {
    errors.postalCode = "Enter a valid postal code.";
  }
  if (!address.country.trim()) errors.country = "Country is required.";
  if (!address.phone.trim()) {
    errors.phone = "Phone number is required.";
  } else if (!/^[+0-9()\s-]{7,20}$/.test(address.phone.trim())) {
    errors.phone = "Enter a valid phone number.";
  }

  return errors;
}

export default function CheckoutPage({
  cartItems,
  onBackToCart,
  onPay,
  shippingFee = 5.99,
}: CheckoutPageProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<AddressErrors>({});
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});
  const [isPaying, setIsPaying] = useState(false);
  const [payError, setPayError] = useState<string | null>(null);

  const subtotal = useMemo(
    () => cartItems.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0),
    [cartItems]
  );
  const tax = useMemo(() => subtotal * 0.08, [subtotal]);
  const total = subtotal + tax + (cartItems.length > 0 ? shippingFee : 0);

  const handleFieldChange = (field: keyof DeliveryAddress, value: string) => {
    setAddress((prev) => ({ ...prev, [field]: value }));
  };

  const handleFieldBlur = (field: keyof DeliveryAddress) => {
    setTouched((prev) => ({ ...prev, [field]: true }));
    setErrors(validateAddress({ ...address }));
  };

  const handlePay = async () => {
    const validationErrors = validateAddress(address);
    setErrors(validationErrors);
    setTouched({
      fullName: true,
      street: true,
      city: true,
      state: true,
      postalCode: true,
      country: true,
      phone: true,
    });

    if (Object.keys(validationErrors).length > 0 || cartItems.length === 0) {
      return;
    }

    setPayError(null);
    setIsPaying(true);
    try {
      await onPay(address);
    } catch (err) {
      setPayError(
        err instanceof Error ? err.message : "Payment failed. Please try again."
      );
    } finally {
      setIsPaying(false);
    }
  };

  const fieldError = (field: keyof DeliveryAddress) =>
    touched[field] ? errors[field] : undefined;

  return (
    <div className="checkout-page">
      <div className="checkout-header">
        <button type="button" className="back-link" onClick={onBackToCart}>
          &larr; Back to cart
        </button>
        <h1>Checkout</h1>
      </div>

      <div className="checkout-layout">
        <section className="checkout-section cart-summary" aria-labelledby="order-summary-heading">
          <h2 id="order-summary-heading">Order Summary</h2>

          {cartItems.length === 0 ? (
            <p className="empty-cart-message">Your cart is empty.</p>
          ) : (
            <ul className="cart-item-list">
              {cartItems.map((item) => (
                <li key={item.id} className="cart-item">
                  <img
                    src={item.imageUrl}
                    alt={item.name}
                    className="cart-item-image"
                  />
                  <div className="cart-item-details">
                    <span className="cart-item-name">{item.name}</span>
                    <span className="cart-item-qty">Qty: {item.quantity}</span>
                  </div>
                  <span className="cart-item-price">
                    {formatCurrency(item.unitPrice * item.quantity)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <div className="totals-breakdown">
            <div className="totals-row">
              <span>Subtotal</span>
              <span>{formatCurrency(subtotal)}</span>
            </div>
            <div className="totals-row">
              <span>Shipping</span>
              <span>
                {cartItems.length > 0 ? formatCurrency(shippingFee) : formatCurrency(0)}
              </span>
            </div>
            <div className="totals-row">
              <span>Tax (8%)</span>
              <span>{formatCurrency(tax)}</span>
            </div>
            <div className="totals-row totals-row-total">
              <span>Total</span>
              <span>{formatCurrency(total)}</span>
            </div>
          </div>
        </section>

        <section className="checkout-section address-form" aria-labelledby="delivery-address-heading">
          <h2 id="delivery-address-heading">Delivery Address</h2>

          <form
            onSubmit={(e) => {
              e.preventDefault();
              handlePay();
            }}
            noValidate
          >
            <div className="form-field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                value={address.fullName}
                onChange={(e) => handleFieldChange("fullName", e.target.value)}
                onBlur={() => handleFieldBlur("fullName")}
                aria-invalid={Boolean(fieldError("fullName"))}
              />
              {fieldError("fullName") && (
                <span className="field-error">{fieldError("fullName")}</span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="street">Street address</label>
              <input
                id="street"
                type="text"
                value={address.street}
                onChange={(e) => handleFieldChange("street", e.target.value)}
                onBlur={() => handleFieldBlur("street")}
                aria-invalid={Boolean(fieldError("street"))}
              />
              {fieldError("street") && (
                <span className="field-error">{fieldError("street")}</span>
              )}
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  value={address.city}
                  onChange={(e) => handleFieldChange("city", e.target.value)}
                  onBlur={() => handleFieldBlur("city")}
                  aria-invalid={Boolean(fieldError("city"))}
                />
                {fieldError("city") && (
                  <span className="field-error">{fieldError("city")}</span>
                )}
              </div>

              <div className="form-field">
                <label htmlFor="state">State / Province</label>
                <input
                  id="state"
                  type="text"
                  value={address.state}
                  onChange={(e) => handleFieldChange("state", e.target.value)}
                  onBlur={() => handleFieldBlur("state")}
                  aria-invalid={Boolean(fieldError("state"))}
                />
                {fieldError("state") && (
                  <span className="field-error">{fieldError("state")}</span>
                )}
              </div>
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  value={address.postalCode}
                  onChange={(e) => handleFieldChange("postalCode", e.target.value)}
                  onBlur={() => handleFieldBlur("postalCode")}
                  aria-invalid={Boolean(fieldError("postalCode"))}
                />
                {fieldError("postalCode") && (
                  <span className="field-error">{fieldError("postalCode")}</span>
                )}
              </div>

              <div className="form-field">
                <label htmlFor="country">Country</label>
                <input
                  id="country"
                  type="text"
                  value={address.country}
                  onChange={(e) => handleFieldChange("country", e.target.value)}
                  onBlur={() => handleFieldBlur("country")}
                  aria-invalid={Boolean(fieldError("country"))}
                />
                {fieldError("country") && (
                  <span className="field-error">{fieldError("country")}</span>
                )}
              </div>
            </div>

            <div className="form-field">
              <label htmlFor="phone">Phone number</label>
              <input
                id="phone"
                type="tel"
                value={address.phone}
                onChange={(e) => handleFieldChange("phone", e.target.value)}
                onBlur={() => handleFieldBlur("phone")}
                aria-invalid={Boolean(fieldError("phone"))}
              />
              {fieldError("phone") && (
                <span className="field-error">{fieldError("phone")}</span>
              )}
            </div>

            {payError && <p className="pay-error">{payError}</p>}

            <div className="checkout-actions">
              <button
                type="button"
                className="secondary-button"
                onClick={onBackToCart}
                disabled={isPaying}
              >
                Back to cart
              </button>
              <button
                type="submit"
                className="pay-button"
                disabled={isPaying || cartItems.length === 0}
              >
                {isPaying ? "Processing..." : `Pay ${formatCurrency(total)}`}
              </button>
            </div>
          </form>
        </section>
      </div>
    </div>
  );
}
```

