**Example usage**
```tsx
import CheckoutPage from "./CheckoutPage";
import type { CartItem, DeliveryAddress } from "./types";

const sampleCartItems: CartItem[] = [
  { id: "1", name: "Wireless Headphones", imageUrl: "/images/headphones.jpg", unitPrice: 79.99, quantity: 1 },
  { id: "2", name: "USB-C Cable (2m)", imageUrl: "/images/cable.jpg", unitPrice: 12.5, quantity: 2 },
];

function App() {
  const handleBackToCart = () => {
    // navigate back to the cart route, e.g. navigate("/cart")
  };

  const handlePay = async (address: DeliveryAddress) => {
    // call your payment/order API here
    await fetch("/api/orders", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ items: sampleCartItems, address }),
    });
  };

  return (
    <CheckoutPage
      cartItems={sampleCartItems}
      onBackToCart={handleBackToCart}
      onPay={handlePay}
    />
  );
}

export default App;
```

Notes on the design:
- `CheckoutPage` is presentation-focused — it takes `cartItems`, `onBackToCart`, and an async `onPay(address)` as props, so you wire it to your router and API.
- Address fields validate on blur and on submit; the Pay button is disabled while the cart is empty or a payment is in flight, and shows a spinner-style "Processing..." label.
- If `onPay` rejects, the error message is shown inline above the actions instead of silently failing.
